#!/usr/bin/env node
/**
 * Pure Node tests for scripts/holo-ci/check-render-surface-native.mjs.
 *
 * The gate's job (render-surface native freeze, D.012/D.014/I.018, 2026-06-05): keep the
 * production render surface HS-native. A render .tsx must be compiler-emitted (carries an
 * "@generated by HoloScript" header) or a compiler example; net-new hand-authored render is
 * blocked, existing hand-authored is grandfathered into an allowlist. These tests build
 * synthetic tiny render trees in a temp dir and assert the verdict — locking the falsifier
 * (block hand-authored / admit generated / admit example) into a permanent regression fence so
 * the gate can't silently rot into a no-op (the exact failure that left check-publish-surface
 * an orphan nobody ran). Hermetic: no install, no network, scoped to a temp --root.
 *
 * Run via: `node scripts/__tests__/check-render-surface-native.test.mjs`.
 */

import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '..', '..');
const SCRIPT = join(REPO_ROOT, 'scripts', 'holo-ci', 'check-render-surface-native.mjs');
const ROOTS = 'packages/r3f-renderer/src'; // single synthetic render root for the fixtures

let testsRun = 0;
let testsFailed = 0;

function assertEq(actual, expected, name) {
  testsRun += 1;
  if (actual === expected) console.log(`  PASS ${name}`);
  else {
    testsFailed += 1;
    console.error(
      `  FAIL ${name}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`
    );
  }
}
function assertMatch(text, re, name) {
  testsRun += 1;
  if (re.test(text)) console.log(`  PASS ${name}`);
  else {
    testsFailed += 1;
    console.error(`  FAIL ${name}: ${re} not found in output:\n${text}`);
  }
}

const GEN_HEADER = '// @generated by HoloScript R3FCompiler — DO NOT EDIT\n';

/** Create a temp workspace; `files` maps a render-root-relative path → contents. */
function setup(files) {
  const dir = mkdtempSync(join(tmpdir(), 'render-surface-test-'));
  mkdirSync(join(dir, 'scripts', 'holo-ci'), { recursive: true }); // allowlist write target
  for (const [rel, body] of Object.entries(files)) {
    const abs = join(dir, ROOTS, rel);
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, body);
  }
  return dir;
}
function run(dir, extra = []) {
  const r = spawnSync(process.execPath, [SCRIPT, '--root', dir, '--roots', ROOTS, ...extra], {
    encoding: 'utf8',
  });
  return { code: r.status, out: (r.stdout || '') + (r.stderr || '') };
}
function runWithRoots(dir, roots, extra = []) {
  const r = spawnSync(process.execPath, [SCRIPT, '--root', dir, '--roots', roots, ...extra], {
    encoding: 'utf8',
  });
  return { code: r.status, out: (r.stdout || '') + (r.stderr || '') };
}
function addFile(dir, rel, body) {
  const abs = join(dir, ROOTS, rel);
  mkdirSync(dirname(abs), { recursive: true });
  writeFileSync(abs, body);
}
function cleanup(dir) {
  rmSync(dir, { recursive: true, force: true });
}

console.log('check-render-surface-native.test.mjs');

// 1. --update seeds the grandfather list; a follow-up check is green and counts correctly.
{
  const dir = setup({
    'Legacy.tsx': 'export const Legacy = () => <mesh />;\n',
    'Gen.tsx': GEN_HEADER + 'export const Gen = () => <mesh />;\n',
    'Widget.test.tsx': 'export const t = () => <mesh />;\n',
    '__tests__/Inner.tsx': 'export const i = () => <mesh />;\n',
  });
  const seed = run(dir, ['--update']);
  assertEq(seed.code, 0, '--update seeds allowlist → exit 0');
  assertMatch(
    seed.out,
    /1 grandfathered hand-authored/,
    'seed counts 1 legacy (Gen=generated, test/__tests__=examples)'
  );
  const chk = run(dir);
  assertEq(chk.code, 0, 'post-seed check → exit 0');
  assertMatch(
    chk.out,
    /1 compiler-generated, 2 examples, 1 grandfathered/,
    'check reports generated/example/legacy split'
  );
  cleanup(dir);
}

// 2. THE FREEZE: a net-new hand-authored render .tsx not in the allowlist → exit 1.
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  run(dir, ['--update']);
  addFile(dir, 'Sneaky.tsx', 'export const Sneaky = () => <mesh />;\n');
  const r = run(dir);
  assertEq(r.code, 1, 'net-new hand-authored render .tsx → exit 1 (BLOCKED)');
  assertMatch(
    r.out,
    /SURFACE-GREW\s+packages\/r3f-renderer\/src\/Sneaky\.tsx/,
    'names the offending net-new file'
  );
  cleanup(dir);
}

// 3. The same net-new file PASSES once it carries a generation header (compiler-emitted).
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  run(dir, ['--update']);
  addFile(dir, 'Sneaky.tsx', GEN_HEADER + 'export const Gen = () => <mesh />;\n');
  const r = run(dir);
  assertEq(r.code, 0, 'net-new WITH @generated header → exit 0 (admitted as HS-native)');
  cleanup(dir);
}

// 3b. The forward-looking @holoscript-generated token is also admitted.
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  run(dir, ['--update']);
  addFile(
    dir,
    'FromHs.tsx',
    '// @holoscript-generated source=foo.hs\nexport const X = () => <mesh />;\n'
  );
  const r = run(dir);
  assertEq(r.code, 0, '@holoscript-generated token → exit 0 (admitted)');
  cleanup(dir);
}

// 4. A net-new COMPILER EXAMPLE (the exception) is admitted without allowlisting.
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  run(dir, ['--update']);
  addFile(dir, 'Demo.stories.tsx', 'export const s = () => <mesh />;\n');
  addFile(dir, 'examples/Sample.tsx', 'export const e = () => <mesh />;\n');
  const r = run(dir);
  assertEq(r.code, 0, 'compiler examples (*.stories.tsx, examples/) → exit 0 (exception)');
  cleanup(dir);
}

// 5. Missing allowlist (gate never seeded) fails loud — not a silent pass.
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  const r = run(dir); // no --update first
  assertEq(r.code, 1, 'missing allowlist → exit 1 (fail loud, no silent pass)');
  assertMatch(r.out, /ALLOWLIST missing/, 'explains the allowlist is missing');
  cleanup(dir);
}

// 6. Allowlisted file that disappeared → SURFACE-SHRANK reconcile prompt (exit 1).
{
  const dir = setup({
    'Legacy.tsx': 'export const L = () => <mesh />;\n',
    'Other.tsx': 'export const O = () => <mesh />;\n',
  });
  run(dir, ['--update']);
  rmSync(join(dir, ROOTS, 'Other.tsx'));
  const r = run(dir);
  assertEq(r.code, 1, 'allowlisted file removed → exit 1 (reconcile)');
  assertMatch(
    r.out,
    /SURFACE-SHRANK\s+packages\/r3f-renderer\/src\/Other\.tsx/,
    'names the vanished allowlist entry'
  );
  cleanup(dir);
}

// 7. Allowlisted file that gained a header → MIGRATED-CAN-PRUNE (informational, still green).
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  run(dir, ['--update']);
  addFile(dir, 'Legacy.tsx', GEN_HEADER + 'export const L = () => <mesh />;\n'); // migrated to generated
  const r = run(dir);
  assertEq(r.code, 0, 'allowlisted file now generated → exit 0 (still green)');
  assertMatch(
    r.out,
    /MIGRATED-CAN-PRUNE\s+packages\/r3f-renderer\/src\/Legacy\.tsx/,
    'flags the migrated file as prunable'
  );
  cleanup(dir);
}

// 8. --files (staged-scope): only the named paths are judged — a peer's unstaged net-new render
//    .tsx on disk does NOT block, but a STAGED net-new one still does (the multi-agent fix, D.077).
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  run(dir, ['--update']); // allowlist = [Legacy]
  addFile(dir, 'PeerWip.tsx', 'export const P = () => <mesh />;\n'); // unstaged peer net-new on disk
  addFile(dir, 'Mine.tsx', 'export const M = () => <mesh />;\n'); // a net-new file, not allowlisted
  const onlyAllowed = run(dir, ['--files', 'packages/r3f-renderer/src/Legacy.tsx']);
  assertEq(
    onlyAllowed.code,
    0,
    "--files scopes to staged: peer's unstaged net-new on disk does NOT block (exit 0)"
  );
  const stagedNew = run(dir, ['--files', 'packages/r3f-renderer/src/Mine.tsx']);
  assertEq(
    stagedNew.code,
    1,
    '--files still blocks a STAGED net-new hand-authored render (exit 1)'
  );
  assertMatch(
    stagedNew.out,
    /SURFACE-GREW\s+packages\/r3f-renderer\/src\/Mine\.tsx/,
    'names the staged offender'
  );
  cleanup(dir);
}

// 9. HoloShell scene adapters are stricter than the generic allowlist: even grandfathered
//    hand-authored scene TSX must have sibling native source ownership.
{
  const dir = setup({
    'components/holoshell/scenes/HandScene.tsx': 'export const HandScene = () => <group />;\n',
  });
  run(dir, ['--update']);
  const missing = run(dir);
  assertEq(
    missing.code,
    1,
    'allowlisted HoloShell scene TSX without native sibling source -> exit 1'
  );
  assertMatch(
    missing.out,
    /NATIVE-SOURCE-MISSING\s+packages\/r3f-renderer\/src\/components\/holoshell\/scenes\/HandScene\.tsx/,
    'names HoloShell scene lacking native source'
  );
  addFile(
    dir,
    'components/holoshell/scenes/HandScene.holo',
    'composition "Hand Scene" { object "SceneLifecycle" { scene_id: "HandScene" } }\n'
  );
  const fixed = run(dir);
  assertEq(fixed.code, 0, 'HoloShell scene TSX with sibling native source -> exit 0');
  cleanup(dir);
}

// 10. A focused --roots run reconciles only entries under the active roots; studio allowlist
//     entries must not appear as false SURFACE-SHRANK errors during an r3f-only ratchet.
{
  const dir = setup({ 'Legacy.tsx': 'export const L = () => <mesh />;\n' });
  mkdirSync(join(dir, 'packages', 'studio', 'src'), { recursive: true });
  writeFileSync(join(dir, 'packages', 'studio', 'src', 'LegacyStudio.tsx'), 'export const S = () => null;\n');
  addFile(dir, 'components/holoshell/scenes/OwnedScene.tsx', 'export const O = () => <group />;\n');
  addFile(
    dir,
    'components/holoshell/scenes/OwnedScene.holo',
    'composition "Owned Scene" { object "SceneLifecycle" { scene_id: "OwnedScene" } }\n'
  );
  runWithRoots(dir, 'packages/r3f-renderer/src,packages/studio/src', ['--update']);
  const r = runWithRoots(dir, 'packages/r3f-renderer/src');
  assertEq(r.code, 0, 'focused r3f --roots ignores out-of-scope studio allowlist entries');
  cleanup(dir);
}

if (testsFailed > 0) {
  console.error(`\n${testsFailed}/${testsRun} tests failed`);
  process.exit(1);
}
console.log(`\n${testsRun}/${testsRun} tests passed`);
